def serialize(obj):
    """ Serialize Python object to PDF syntax byte string """
    if isinstance(obj, dict):
        items = []
        for k, v in obj.items():
            items.append(serialize(k))
            items.append(serialize(v))
        return b'<< ' + b' '.join(items) + b' >>'
    elif isinstance(obj, list):
        items = [serialize(item) for item in obj]
        return b'[ ' + b' '.join(items) + b' ]'
    elif isinstance(obj, bool):
        return b'true' if obj else b'false'
    elif isinstance(obj, int) or isinstance(obj, float):
        return str(obj).encode('ascii')
    elif isinstance(obj, str):
        # Handle string serialization (for names and literals)
        if obj.startswith('/'):
            return obj.encode('ascii')
        else:
            # For literal strings, we need to encode them properly
            return b'(' + obj.encode('utf-8') + b')'
    elif isinstance(obj, bytes):
        return obj
    else:
        # Default to string representation
        return str(obj).encode('ascii')


def next_token(text, i=0):
    """ syntax Find next token in raw string starting at some index
    """
    search = "TBD"
    nested = 1
    h = i
    while i < len(text):
        single = text[i:i+1]
        double = text[i:i+2]
        if search == "TBD":
            if double == b'<<':
                search = "DICT"
            elif single == b'[':
                search = "ARRAY"
            elif single == b"/":
                search = "NAME"
            elif text[i:i+6] == b"stream":
                search = "STREAM"
                offset = 7 if text[i+6:i+7] == b'\n' else 8 # else is b'\r\n'
                i += offset
            elif single in b"+-.0123456789":
                search = "VALUE"
            elif single in b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ":
                search = "KEYWORD"
            elif single in b"(<":
                search = "TEXT"
            elif single == b't':
                # Check for true/false keywords
                if text[i:i+4] == b'true':
                    return (i, i+4, 'TRUE')
                elif text[i:i+5] == b'false':
                    return (i, i+5, 'FALSE')
            elif single == b'%':
                # Skip comment
                while i < len(text) and text[i:i+1] not in b'\r\n':
                    i += 1
                while i < len(text) and text[i:i+1] in b'\r\n':
                    i += 1
                return (i, i, 'COMMENT')
            h = i
        elif search == "DICT":
            if double == b'<<':
                nested += 1
                i += 1
            elif double == b'>>':
                nested -= 1
                i += 1
            if nested == 0:
                return (h, i + 1, 'DICT')
        elif search == "NAME":
            if single in b' \n\r[]/<>(':
                return (h, i, 'NAME')
            i += 1
            continue
        elif search == "TEXT":
            if double == b'\\(' or double == b'\\)' or double == b'\\<' or double == b'\\>':
                i += 1
            elif single == b'(':
                # Handle opening parenthesis in literal strings
                paren_count = 1
                i += 1
                while i < len(text) and paren_count > 0:
                    if text[i:i+1] == b'(':
                        paren_count += 1
                    elif text[i:i+1] == b')':
                        paren_count -= 1
                    i += 1
                return (h, i, 'STRING')
            elif single == b'<':
                # Handle hexadecimal strings
                i += 1
                while i < len(text) and text[i:i+1] not in b'>':
                    i += 1
                if i < len(text) and text[i:i+1] == b'>':
                    i += 1
                return (h, i, 'STRING')
            elif single in b')>':
                return (h, i + 1, 'STRING')
            i += 1
            continue
        elif search == "KEYWORD":
            if single in b' \n\r>/]' or i == len(text) - 1:
                # Check if it's a special keyword
                keyword = text[h:i]
                if keyword == b'true':
                    return (h, i, 'TRUE')
                elif keyword == b'false':
                    return (h, i, 'FALSE')
                return (h, i, 'KEYWORD')
        elif search == "VALUE":
            if single in b' \n\r>/]' or i == len(text) - 1:
                # Determine if it's integer or real
                if b'.' in text[h:i] or b'e' in text[h:i].lower():
                    return (h, i, 'REAL')
                else:
                    return (h, i, 'INTEGER')
        elif search == "STREAM":
            if text[i:i+11] == b'\r\nendstream' or text[i:i+10] == b'\nendstream':
                return (h, i, 'STREAM')
        elif search == "ARRAY":
            if single == b'[':
                nested += 1
            elif single == b']':
                nested -= 1
            if nested == 0:
                return (h, i + 1, 'ARRAY')
        i += 1

    # Handle incomplete tokens at end of string
    if search == "NAME":
        return (h, i, None)
    elif search == "VALUE":
        # Return incomplete VALUE token
        return (h, i, None)
    elif search == "TEXT":
        # Incomplete TEXT token
        return (h, i, None)
    elif search == "DICT":
        # Incomplete DICT token
        return (h, i, None)
    elif search == "ARRAY":
        # Incomplete ARRAY token
        return (h, i, None)

    return (h, i, None)


def replace_ref(tokens):
    """ syntax
    """
    size = len(tokens)
    new_list = []
    i = 0
    while i < size:
        if i < size - 2 and tokens[i + 2] == b'R':
            # Create a complex number representation for reference (as done in original)
            # This follows the convention that 6 0 R becomes 6j
            ref_num = int(tokens[i])
            new_list.append(ref_num)
            i += 3
        else:
            new_list.append(tokens[i])
            i += 1
    return new_list

def decode_predictor(bdata, predictor, columns):
    size = len(bdata)
    res = b''
    columns += 1
    prev_row = [0] * columns
    i = 0
    while i < size:
        row = list(bdata[i:i+columns])
        decoded_row = [(val + prev_row[index]) & 0xff for (index, val) in enumerate(row)]
        prev_row = decoded_row
        res += bytes(decoded_row[1:])
        i += columns
    return res


def decode_stream(stream, stream_def):
    res = stream
    if b'/Filter' in stream_def and stream_def[b'/Filter'] == b'/FlateDecode':
        res = zlib.decompress(stream) #+ b'\r')
    if b'/DecodeParms' in stream_def and b'/Predictor' in stream_def[b'/DecodeParms']:
        predictor = int(stream_def[b'/DecodeParms'][b'/Predictor'])
        columns = int(stream_def[b'/DecodeParms'][b'/Columns'])
        res = decode_predictor(res, predictor, columns)
    return res


def parse_obj(text, start=0):
    """ syntax
    """
    h1, j1, t1 = next_token(text, start)
    if t1 == 'DICT':
        res = {}
        i = h1 + 2  # Skip the << 
        while i < j1 - 2:  # Skip the >>
            # Parse key
            h_key, i, t_key = next_token(text, i)
            if t_key == 'NAME':
                key = text[h_key:i].decode('ascii')
            elif t_key == 'KEYWORD':
                key = text[h_key:i].decode('ascii')
            else:
                # Skip invalid keys
                continue

            # Parse value
            h_val, i, t_val = next_token(text, i)
            if t_val:
                if t_val == 'DICT':
                    obj = parse_obj(text[h_val:i])
                elif t_val == 'ARRAY':
                    obj = parse_obj(text[h_val:i])
                elif t_val == 'TRUE':
                    obj = True
                elif t_val == 'FALSE':
                    obj = False
                elif t_val == 'NAME':
                    obj = text[h_val:i].decode('ascii')
                elif t_val == 'INTEGER' or t_val == 'REAL':
                    try:
                        obj = float(text[h_val:i]) if b'.' in text[h_val:i] or b'e' in text[h_val:i].lower() else int(text[h_val:i])
                    except ValueError:
                        # If conversion fails, treat as string
                        obj = text[h_val:i]
                elif t_val == 'STRING':
                    obj = text[h_val:i]
                else:
                    obj = text[h_val:i]
                res[key] = obj
        return res

    elif t1 == 'ARRAY':
        res = []
        i = h1 + 1  # Skip the [
        while i < j1 - 1:  # Skip the ]
            h, i, ttt = next_token(text, i)
            if ttt:
                if ttt == 'DICT':
                    obj = parse_obj(text[h:i])
                elif ttt == 'ARRAY':
                    obj = parse_obj(text[h:i])
                elif ttt == 'TRUE':
                    obj = True
                elif ttt == 'FALSE':
                    obj = False
                elif ttt == 'NAME':
                    obj = text[h:i].decode('ascii')
                elif ttt == 'INTEGER' or ttt == 'REAL':
                    try:
                        obj = float(text[h:i]) if b'.' in text[h:i] or b'e' in text[h:i].lower() else int(text[h:i])
                    except ValueError:
                        # If conversion fails, treat as string
                        obj = text[h:i]
                elif ttt == 'STRING':
                    obj = text[h:i]
                else:
                    obj = text[h:i]
                res.append(obj)
        res = replace_ref(res)
        return res
    elif t1 == 'TRUE':
        return True
    elif t1 == 'FALSE':
        return False
    else:
        return None


